def check_required() -> list[str]:
    return [f"missing required file: {name}" for name in REQUIRED if not (REPOSITORY / name).is_file()]


def check_links() -> list[str]:
    failures: list[str] = []
    for source in REPOSITORY.rglob("*.md"):
        text = source.read_text(encoding="utf-8")
        for match in LINK_PATTERN.finditer(text):
            raw = match.group(1).strip()
            if raw.startswith("<") and raw.endswith(">"):
                raw = raw[1:-1]
            # Drop an optional Markdown link title after a whitespace separator.
            target = raw.split(maxsplit=1)[0]
            if target.startswith(("http://", "https://", "mailto:", "#")):
                continue
            path_text = unquote(target.split("#", 1)[0])
            if not path_text:
                continue
            destination = (source.parent / path_text).resolve()
            if not destination.exists():
                relative = source.relative_to(REPOSITORY)
                failures.append(f"broken local link in {relative}: {target}")
    return failures


def check_public_text() -> list[str]:
    failures: list[str] = []
    forbidden = {
        "github.com/OWNER": "unresolved repository-owner placeholder",
        "/Users/admin/": "developer-specific absolute path",
        "machine-precision validation": "retired overclaim",
    }
    for path in canonical_files():
        if path.resolve() == Path(__file__).resolve():
            continue
        if path.suffix.lower() not in {".md", ".toml", ".cff", ".py", ".bib"}:
            continue
        text = path.read_text(encoding="utf-8")
        for phrase, explanation in forbidden.items():
            if phrase in text:
                # The README and ledger may name a retired phrase while explicitly
                # documenting its retirement.  Only placeholders/paths are global.
                if phrase == "machine-precision validation" and path.name in {
                    "README.md",
                    "claim-ledger.md",
                    "review-summary.md",
                }:
                    continue
                failures.append(
                    f"{path.relative_to(REPOSITORY)}: {explanation}: {phrase!r}"
                )
    return failures


