def _read_public_surface(relative: str) -> str:
    return (REPOSITORY / relative).read_text(encoding="utf-8")


def _require_surface_phrases(
    relative: str,
    phrases: tuple[str, ...],
    failures: list[str],
) -> None:
    try:
        content = _read_public_surface(relative)
    except OSError as exc:
        failures.append(f"cannot read framework surface {relative}: {exc}")
        return
    for phrase in phrases:
        if phrase not in content:
            failures.append(
                f"{relative}: missing Phase -1 authority-boundary phrase {phrase!r}"
            )


def check_fgc_alignment() -> list[str]:
    """Keep FGC, NGS, and Phase -1 authority-boundary contracts canonical."""

    failures: list[str] = []
    for relative, phrases in PHASE_MINUS1_REQUIRED_PHRASES.items():
        _require_surface_phrases(relative, phrases, failures)
    return failures


def check_git_data_boundary() -> list[str]:
    failures: list[str] = []
    inside_git = subprocess.run(
        ["git", "rev-parse", "--is-inside-work-tree"],
        cwd=REPOSITORY,
        capture_output=True,
        text=True,
    )
    if inside_git.returncode != 0:
        ignore_lines = {
            line.strip()
            for line in (REPOSITORY / ".gitignore").read_text(encoding="utf-8").splitlines()
            if line.strip() and not line.lstrip().startswith("#")
        }
        if "collected-data/*.fits" not in ignore_lines:
            failures.append(".gitignore does not exclude collected-data/*.fits")
        return failures

    completed = subprocess.run(
        ["git", "ls-files", "--", "collected-data/*.fits"],
        cwd=REPOSITORY,
        check=True,
        capture_output=True,
        text=True,
    )
    if completed.stdout.strip():
        failures.append("large third-party FITS files are tracked by Git")
    for name in ("smica_2048.fits", "mask_common.fits"):
        checked = subprocess.run(
            ["git", "check-ignore", "-q", f"collected-data/{name}"],
            cwd=REPOSITORY,
        )
        if checked.returncode != 0:
            failures.append(f"collected-data/{name} is not covered by .gitignore")
    return failures


def check_reference_sequence() -> list[str]:
    manuscript = (REPOSITORY / "paper" / "recursive-horizons.md").read_text(encoding="utf-8")
    try:
        references = manuscript.split("# References\n", 1)[1]
    except IndexError:
        return ["manuscript has no References section"]
    numbers = [int(value) for value in re.findall(r"(?m)^(\d+)\. ", references)]
    if not numbers:
        return ["manuscript reference list is empty"]
    expected = list(range(1, max(numbers) + 1))
    failures = []
    if numbers != expected:
        failures.append("manuscript references are not a contiguous 1..N sequence")
    body = manuscript.split("# References\n", 1)[0]
    citations = [
        int(value)
        for group in re.findall(r"\[([0-9, ]+)\]", body)
        for value in group.replace(" ", "").split(",")
        if value
    ]
    missing = sorted(set(expected) - set(citations))
    out_of_range = sorted(set(citations) - set(expected))
    if missing:
        failures.append(f"references never cited in manuscript body: {missing}")
    if out_of_range:
        failures.append(f"out-of-range manuscript citations: {out_of_range}")
    return failures

